#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    for (int i = 0; i < n; i++) {
        while (a[i] > 0 && a[i] <= n && a[a[i] - 1] != a[i]) {
            int tmp = a[a[i] - 1];
            a[a[i] - 1] = a[i];
            a[i] = tmp;
        }
    }
    for (int i = 0; i < n; i++) {
        if (a[i] != i + 1) { printf("%d\n", i + 1); free(a); return 0; }
    }
    printf("%d\n", n + 1); free(a);
    return 0;
}

